from __future__ import annotations

from typing import Any


def parse_text_table(text: str) -> list[dict[str, Any]]:
    """Parse pipe-delimited text table rows into dictionaries.

    The function is deliberately dependency-free so it can run in a sandboxed
    runtime. It ignores separator rows and returns an empty list when no valid
    header/data rows are present.
    """
    lines = [line.strip() for line in str(text or "").splitlines() if "|" in line]
    rows: list[list[str]] = []
    for line in lines:
        cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
        if len(cells) < 2:
            continue
        if all(cell and set(cell) <= set("-: ") for cell in cells):
            continue
        rows.append(cells)
    if len(rows) < 2:
        return []
    header = rows[0]
    output: list[dict[str, Any]] = []
    for row in rows[1:]:
        item: dict[str, Any] = {}
        for index, name in enumerate(header):
            key = name or f"column_{index + 1}"
            item[key] = row[index] if index < len(row) else ""
        output.append(item)
    return output


def run(input_data: Any = None, **kwargs: Any) -> dict[str, Any]:
    if isinstance(input_data, dict):
        text = input_data.get("text") or input_data.get("content") or ""
    elif input_data is None:
        text = kwargs.get("text") or kwargs.get("content") or ""
    else:
        text = str(input_data)
    rows = parse_text_table(str(text or ""))
    return {
        "status": "completed",
        "row_count": len(rows),
        "rows": rows,
    }

from __future__ import annotations

import base64
import io
import zipfile
import xml.etree.ElementTree as ET
from pathlib import Path
from typing import Any


def _read_bytes(input_data: dict[str, Any]) -> bytes:
    if input_data.get("bytes_base64"):
        return base64.b64decode(str(input_data.get("bytes_base64")))
    if input_data.get("docx_base64"):
        return base64.b64decode(str(input_data.get("docx_base64")))
    path_value = input_data.get("path") or input_data.get("file_path")
    if path_value:
        return Path(str(path_value)).read_bytes()
    raw = input_data.get("bytes")
    if isinstance(raw, bytes):
        return raw
    raise ValueError("DOCX input requires path, file_path, bytes, bytes_base64, or docx_base64.")


def extract_docx_text_from_bytes(data: bytes) -> str:
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        xml_bytes = archive.read("word/document.xml")
    root = ET.fromstring(xml_bytes)
    namespace = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
    paragraphs: list[str] = []
    for paragraph in root.iter(namespace + "p"):
        parts: list[str] = []
        for node in paragraph.iter(namespace + "t"):
            if node.text:
                parts.append(node.text)
        if parts:
            paragraphs.append("".join(parts))
    return "\n".join(paragraphs).strip()


def run(input_data: Any = None, **kwargs: Any) -> dict[str, Any]:
    payload = input_data if isinstance(input_data, dict) else {}
    payload = {**payload, **kwargs}
    try:
        data = _read_bytes(payload)
        text = extract_docx_text_from_bytes(data)
        paragraphs = [line for line in text.splitlines() if line.strip()]
        return {
            "status": "completed",
            "text": text,
            "paragraph_count": len(paragraphs),
            "character_count": len(text),
        }
    except Exception as exc:
        return {
            "status": "failed",
            "error": {"type": exc.__class__.__name__, "message": str(exc)},
            "text": "",
            "paragraph_count": 0,
            "character_count": 0,
        }

from __future__ import annotations

from typing import Any


def run(input_data: Any = None, **kwargs: Any) -> dict[str, Any]:
    payload = input_data if isinstance(input_data, dict) else {}
    payload = {**payload, **kwargs}
    runtime = payload.get('_runtime') if isinstance(payload.get('_runtime'), dict) else {}
    connection = runtime.get('connection') if isinstance(runtime.get('connection'), dict) else {}
    secrets = runtime.get('secrets') if isinstance(runtime.get('secrets'), dict) else {}
    configured = bool(connection)
    secret_available = bool(secrets)
    return {
        'status': 'completed' if configured and secret_available else 'failed',
        'data': {
            'configured': configured,
            'secret_available': secret_available,
            'received_keys': sorted([str(k) for k in payload.keys() if k != '_runtime']),
            'connection_keys': sorted([str(k) for k in connection.keys()]),
            'secret_keys': sorted([str(k) for k in secrets.keys()]),
        },
        'configured': configured,
        'secret_available': secret_available,
    }

from __future__ import annotations

import smtplib
from email.message import EmailMessage
from typing import Any


def _runtime_section(payload: dict[str, Any]) -> dict[str, Any]:
    runtime = payload.get("_runtime") if isinstance(payload.get("_runtime"), dict) else {}
    return runtime


def _as_list(value: Any) -> list[str]:
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    if isinstance(value, str) and value.strip():
        return [value.strip()]
    return []


def _build_message(content: dict[str, Any], connection: dict[str, Any]) -> EmailMessage:
    sender = str(content.get("sender") or connection.get("default_sender") or "").strip()
    targets = _as_list(content.get("targets"))
    title = str(content.get("title") or "").strip()
    body = str(content.get("body") or "")
    if not sender:
        raise ValueError("sender or runtime connection default_sender is required")
    if not targets:
        raise ValueError("message.targets is required")
    if not title:
        raise ValueError("message.title is required")
    msg = EmailMessage()
    msg["From"] = sender
    msg["To"] = ", ".join(targets)
    cc = _as_list(content.get("cc"))
    if cc:
        msg["Cc"] = ", ".join(cc)
    msg["Subject"] = title
    msg.set_content(body)
    return msg


def run(payload: dict[str, Any] | None = None) -> dict[str, Any]:
    data = payload if isinstance(payload, dict) else {}
    runtime = _runtime_section(data)
    connection = runtime.get("connection") if isinstance(runtime.get("connection"), dict) else {}
    secrets = runtime.get("secrets") if isinstance(runtime.get("secrets"), dict) else {}
    secret_refs = runtime.get("secret_refs") if isinstance(runtime.get("secret_refs"), dict) else {}
    content = data.get("message") if isinstance(data.get("message"), dict) else {}
    mode = str(data.get("mode") or "prepare").lower()
    if not connection:
        return {"status": "requires_configuration", "data": {"configured": False, "reason": "runtime_connection_profile_missing"}}
    if not secrets and not secret_refs:
        return {"status": "requires_configuration", "data": {"configured": False, "reason": "runtime_secret_reference_missing"}}
    try:
        msg = _build_message(content, connection)
    except Exception as exc:
        return {"status": "failed", "error": {"type": exc.__class__.__name__, "message": str(exc)}}
    recipients = _as_list(content.get("targets")) + _as_list(content.get("cc")) + _as_list(content.get("bcc"))
    security_mode = str(connection.get("security_mode") or "sandbox").lower()
    if mode in {"verify", "dry_run", "prepare"} or security_mode == "sandbox":
        return {"status": "success", "data": {"configured": True, "message_constructed": True, "recipient_count": len(recipients), "external_action_executed": False, "verification_only": mode == "verify"}, "provenance": {"secret_values_exposed": False}}
    if mode == "send" and not bool(data.get("approved")):
        return {"status": "requires_approval", "data": {"external_action_executed": False, "preview": {"recipient_count": len(recipients), "title": str(content.get("title") or "")}}}
    host = str(connection.get("server_host") or "").strip()
    port = int(connection.get("server_port") or (465 if security_mode == "ssl" else 587))
    username = str(connection.get("username") or "").strip()
    password = str(secrets.get("password") or "")
    try:
        client_cls = smtplib.SMTP_SSL if security_mode == "ssl" else smtplib.SMTP
        with client_cls(host, port, timeout=20) as client:
            if security_mode == "starttls":
                client.starttls()
            if username and password:
                client.login(username, password)
            client.send_message(msg, to_addrs=recipients)
        return {"status": "success", "data": {"external_action_executed": True, "recipient_count": len(recipients)}, "provenance": {"secret_values_exposed": False}}
    except Exception as exc:
        return {"status": "failed", "error": {"type": exc.__class__.__name__, "message": str(exc)}, "data": {"external_action_executed": False}}

from tool import run


def test_requires_runtime_profile():
    result = run({"message": {"targets": ["a@example.invalid"], "title": "T", "body": "B"}})
    assert result["status"] == "requires_configuration"


def test_verify_constructs_message_without_external_delivery():
    result = run({
        "mode": "verify",
        "message": {"targets": ["a@example.invalid"], "title": "T", "body": "B"},
        "_runtime": {
            "connection": {"server_host": "localhost", "server_port": 1025, "security_mode": "sandbox", "username": "tester", "default_sender": "sender@example.invalid"},
            "secrets": {"password": "hidden"},
            "secret_refs": {"password": "runtime-secret-ref"},
        },
    })
    assert result["status"] == "success"
    assert result["data"]["configured"] is True
    assert result["data"]["message_constructed"] is True
    assert result["data"]["external_action_executed"] is False


def test_send_requires_approval_before_external_action():
    result = run({
        "mode": "send",
        "message": {"targets": ["a@example.invalid"], "title": "T", "body": "B"},
        "_runtime": {
            "connection": {"server_host": "localhost", "server_port": 1025, "security_mode": "plain", "username": "tester", "default_sender": "sender@example.invalid"},
            "secrets": {"password": "hidden"},
            "secret_refs": {"password": "runtime-secret-ref"},
        },
    })
    assert result["status"] == "requires_approval"
    assert result["data"]["external_action_executed"] is False
